var indexTemplate = template.Must(template.New("index").Parse(`<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>ToCloud9 Test Realms</title><style>
*{box-sizing:border-box}body{font:16px system-ui,sans-serif;background:#10131a;color:#e8edf5;max-width:900px;margin:3rem auto;padding:0 1rem}button,select,input{font:inherit;padding:.65rem;border-radius:.4rem;border:1px solid #556;background:#202634;color:#fff;max-width:100%}select{width:min(100%,42rem);text-overflow:ellipsis}button{cursor:pointer;background:#356ae6}button:disabled,select:disabled,input:disabled{opacity:.45;cursor:not-allowed}section{background:#181d28;padding:1.2rem;margin:1rem 0;border-radius:.6rem;overflow:hidden}.muted{color:#aab4c5}.error{color:#ff8a8a}.danger{color:#fff;background:#8b1d25;border:2px solid #ff6570;padding:1rem;border-radius:.5rem;font-weight:700}#status.error{padding:.8rem;border:1px solid #a63d48;border-radius:.45rem;background:#391d24;color:#ffb3b8}#status.ok{padding:.8rem;border:1px solid #326e4a;border-radius:.45rem;background:#183325;color:#9ee8b6}.row{display:flex;gap:.8rem;align-items:end;flex-wrap:wrap;margin:.6rem 0}.row>label{display:grid;gap:.3rem;align-content:end}.row>label:has(input[type=checkbox]){display:flex;align-items:center;padding-bottom:.7rem}.row input[type=number]{width:9rem}.row input[type=checkbox]{width:auto}.row select{width:11rem;min-height:2.8rem}.details{display:grid;grid-template-columns:max-content 1fr;gap:.4rem 1rem}.details dd{margin:0;overflow-wrap:anywhere}input{width:16rem}ul{padding-left:1.2rem}#loading{position:fixed;inset:0;background:#10131af2;display:grid;place-content:center;z-index:10;padding:1rem;overflow:auto}#loading[hidden]{display:none}.loading-card{width:min(52rem,calc(100vw - 2rem));background:#181d28;border:1px solid #394256;border-radius:.8rem;padding:1.5rem;text-align:left;box-shadow:0 1rem 4rem #0008}.loading-head{text-align:center}.spinner{width:3rem;height:3rem;border:.35rem solid #445;border-top-color:#6b96ff;border-radius:50%;animation:spin 1s linear infinite;margin:auto}.steps{display:flex;list-style:none;padding:0;margin:2rem 0 1.4rem;counter-reset:step}.steps li{position:relative;flex:1;padding:2.3rem .25rem 0;text-align:center;color:#7f8a9d;font-size:.82rem;counter-increment:step}.steps li:before{content:counter(step);position:absolute;z-index:2;top:0;left:50%;transform:translateX(-50%);display:grid;place-items:center;width:1.9rem;height:1.9rem;border:2px solid #4b5569;border-radius:50%;background:#181d28;color:#9aa5b8;font-weight:700}.steps li:not(:last-child):after{content:'';position:absolute;z-index:1;top:.9rem;left:calc(50% + .95rem);width:calc(100% - 1.9rem);height:3px;background:#394256}.steps li.active{color:#fff;font-weight:700}.steps li.active:before{content:'●';border-color:#6b96ff;color:#6b96ff;box-shadow:0 0 0 .3rem #6b96ff22}.steps li.done{color:#b9c4d5}.steps li.done:before{content:'✓';border-color:#69d58c;background:#244533;color:#8cf0a9}.steps li.done:after{background:#69d58c}.step-note{display:block;font-size:.72rem;font-weight:400;color:#8893a7;margin-top:.3rem}#progress{overflow-wrap:anywhere}.elapsed{text-align:center;font-variant-numeric:tabular-nums}@media(max-width:650px){.steps{display:block;margin-left:.5rem}.steps li{text-align:left;padding:0 0 1.3rem 2.6rem}.steps li:before{left:0;transform:none}.steps li:not(:last-child):after{left:.9rem;top:1.9rem;width:3px;height:calc(100% - 1.9rem)}.step-note{font-size:.78rem}}@keyframes spin{to{transform:rotate(360deg)}}</style></head>
<style>#create{display:block;width:100%;padding:1rem 1.25rem;background:#238636;border-color:#3fb950;font-size:1.15rem;font-weight:750}#create:hover:not(:disabled){background:#2ea043}.task-progress{width:100%;height:1.15rem;accent-color:#69d58c}.telemetry{display:flex;justify-content:space-between;gap:1rem;font-size:.82rem;font-variant-numeric:tabular-nums}</style>
<body><h1>ToCloud9 test realms</h1><p class="muted">Select an approved open AzerothCore PR and optionally prepare one testing character.</p>
<section><div id="status">Checking capacity…</div><p><select id="prs"><option>Loading open PRs…</option></select></p></section>
<section id="fixture"><label><input id="realm-only" type="checkbox"> Realm only — do not prepare a character</label><div id="character"><h2>Testing character</h2><p class="muted">Character fixtures are not enabled yet. Select “Realm only” to provision a playable realm.</p><div class="row"><label>Name <input id="char-name" value="Tester" minlength="2" maxlength="12" pattern="[A-Za-z]{2,12}" autocomplete="off" required></label><label>Race <select id="race"><option>human</option><option>orc</option><option>dwarf</option><option>night elf</option><option>undead</option><option>tauren</option><option>gnome</option><option>troll</option><option>blood elf</option><option>draenei</option></select></label><label>Class <select id="class"><option>warrior</option><option>paladin</option><option>hunter</option><option>rogue</option><option>priest</option><option>death knight</option><option>shaman</option><option>mage</option><option>warlock</option><option>druid</option></select></label><label>Level <input id="level" type="number" min="1" max="80" step="1" value="80" required></label><label>Gold <input id="gold" type="number" min="0" max="10000" step="1" value="0" required></label></div><h3>Items</h3><div id="items"></div><button id="add-item" type="button">Add item</button><h3>Quests</h3><div id="quests"></div><button id="add-quest" type="button">Add quest</button></div><p><button id="create" type="button">Create test realm</button></p></section>
<section id="result" hidden></section><section><h2>Manage an existing realm</h2><p><input id="realm-id" maxlength="24" pattern="[a-f0-9]{24}" autocomplete="off" placeholder="Realm ID"></p><p><input id="realm-token" type="password" maxlength="64" pattern="[a-f0-9]{64}" autocomplete="off" placeholder="Management token"></p><button id="inspect">Check</button> <button id="reactivate">Reactivate</button> <button id="delete">Delete permanently</button><pre id="managed"></pre></section>
<section><h2>Current realm IDs</h2><ul id="current-realms"><li class="muted">Loading…</li></ul><h2>Builds in progress</h2><p id="build-capacity" class="muted"></p><ul id="current-builds"><li class="muted">Loading…</li></ul></section>
<div id="loading" hidden><div class="loading-card"><div class="loading-head"><div class="spinner"></div><h2>Provisioning test realm</h2><p id="progress">Validating request…</p><p id="elapsed" class="muted elapsed">Elapsed: 0:00</p></div><ol class="steps"><li id="step-request">Validate request and reserve capacity<span class="step-note">Checks the PR and requested options.</span></li><li id="step-build">Build PR-specific server images<span class="step-note">GitHub Actions compiles AzerothCore and prepares its database importer. Builds continue even when all five online realm slots are occupied.</span></li><li id="step-slot">Allocate an isolated realm slot<span class="step-note">Waits for online capacity, then assigns a realm ID, namespace, private databases, and one-time management token.</span></li><li id="step-db">Prepare databases and cluster services<span class="step-note">Copies the base world, imports the PR database state, and connects shared TC9 services.</span></li><li id="step-server">Start the gateway and AzerothCore server<span class="step-note">Downloads cached client data when needed and waits for both workloads to become healthy.</span></li><li id="step-ready">Register and verify the playable realm<span class="step-note">Adds the realm to the authentication realm list and returns its connection details.</span></li></ol><p class="muted">Keep this page open. A first build can take several minutes; later realms for the same unchanged PR reuse its images.</p></div></div>
<script>
const managementControls=()=>document.querySelectorAll('#realm-id,#realm-token,#inspect,#reactivate,#delete');new MutationObserver(()=>managementControls().forEach(x=>x.disabled=false)).observe(document.body,{subtree:true,attributes:true,attributeFilter:['disabled']});managementControls().forEach(x=>x.disabled=false);
(()=>{let elapsed=document.querySelector('#elapsed'),bar=document.createElement('progress'),meta=document.createElement('div');bar.id='taskbar';bar.max=100;bar.className='task-progress';meta.className='telemetry muted';meta.innerHTML='<span id="task-percent">Measuring task…</span><span id="task-activity">Waiting for activity…</span>';elapsed.before(bar,meta)})();
let telemetryAt=0;function setTelemetry(percent,updated){let bar=q('#taskbar'),valid=Number.isFinite(percent)&&percent>=0;if(valid){bar.value=Math.min(100,percent);q('#task-percent').textContent=Math.round(percent)+'%'}else{bar.removeAttribute('value');q('#task-percent').textContent='Active · progress cannot be measured exactly'}telemetryAt=updated?new Date(updated).getTime():Date.now();updateTelemetryAge()}function updateTelemetryAge(){let age=Math.max(0,Math.floor((Date.now()-telemetryAt)/1000)),label=age<5?'just now':age+'s ago';q('#task-activity').textContent=(age>120?'No new activity for ':'Last activity ')+label;q('#task-activity').className=age>120?'error':''}setInterval(()=>{if(telemetryAt)updateTelemetryAge()},1000);
let available=false,stateGeneration='',lastStatus=null;const q=s=>document.querySelector(s),pendingKey='tc9.pendingRealm.v1';async function api(path,opts={}){let r=await fetch(path,{...opts,headers:{'Content-Type':'application/json',...(opts.headers||{})}}),d=await r.json().catch(()=>({}));if(!r.ok){let e=Error(d.error||r.statusText);e.status=r.status;e.data=d;throw e}return d}
let loadingStarted=0,elapsedTimer;const stageIDs=['request','build','slot','db','server','ready'];function readPending(){try{return JSON.parse(localStorage.getItem(pendingKey))}catch{return null}}function savePending(value){localStorage.setItem(pendingKey,JSON.stringify(value))}function clearPending(){localStorage.removeItem(pendingKey)}function showLoading(started){loadingStarted=started||Date.now();q('#loading').hidden=false;setStage('request','Validating the request and checking available capacity…');clearInterval(elapsedTimer);let tick=()=>{let seconds=Math.max(0,Math.floor((Date.now()-loadingStarted)/1000));q('#elapsed').textContent='Elapsed: '+Math.floor(seconds/60)+':'+String(seconds%60).padStart(2,'0')};tick();elapsedTimer=setInterval(tick,1000)}function hideLoading(){q('#loading').hidden=true;clearInterval(elapsedTimer)}function setStage(stage,message){let current=stageIDs.indexOf(stage);for(let i=0;i<stageIDs.length;i++){let node=q('#step-'+stageIDs[i]);node.className=i<current?'done':i===current?'active':''}q('#progress').textContent=message}
function setInteractive(enabled){document.querySelectorAll('button,input,select').forEach(x=>x.disabled=!enabled)}function unavailableReason(st){if(st.maintenance_message)return st.maintenance_message+' All controls are disabled until maintenance completes.';if(!st.operator_available)return'Realm provisioning is temporarily unavailable because the realm operator is offline. All controls are disabled until it recovers.';if(!st.images_available&&!st.builds_available)return'Realm provisioning is temporarily unavailable because neither approved PR images nor the secure build service are available. All controls are disabled.';return'Realm provisioning is temporarily unavailable. All controls are disabled until the service health check recovers.'}function capacityText(st,o){let builds=o&&o.build_status_available?o.builds.length+'/'+o.max_concurrent_builds:'unavailable',online=st.running_realms+'/'+st.max_running_realms;return'Online realms: '+online+(st.online_capacity_available?'':' (new realms wait)')+' · Build slots: '+builds+' active'}function applyStatus(st){lastStatus=st;if(stateGeneration&&st.state_generation!==stateGeneration)clearPending();stateGeneration=st.state_generation||'';let pending=readPending();if(pending&&pending.stateGeneration!==stateGeneration)clearPending();available=st.available;q('#status').textContent=available?'Service available — '+capacityText(st,null):unavailableReason(st);q('#status').className=available?'ok':'error';setInteractive(available)}function healthFailure(e){available=false;q('#status').textContent='Service health could not be verified: '+e.message+'. All controls are disabled until it recovers.';q('#status').className='error';setInteractive(false)}function terminalFailure(e){return[400,401,403,404,409,410,422].includes(e.status)}async function refreshAvailability(){try{applyStatus(await api('/api/status'))}catch(e){healthFailure(e)}}async function load(){try{let [st,prs]=await Promise.all([api('/api/status'),api('/api/prs')]);applyStatus(st);q('#prs').innerHTML=prs.map(p=>'<option value="'+p.number+'">#'+p.number+' — '+escapeHTML(p.title)+'</option>').join('');await loadOverview()}catch(e){healthFailure(e)}}
async function loadOverview(){try{let o=await api('/api/overview');if(available&&lastStatus){q('#status').textContent='Service available — '+capacityText(lastStatus,o)}q('#current-realms').innerHTML=o.realms.length?o.realms.map(r=>'<li>Realm '+r.realmlist_id+' — management ID <code>'+escapeHTML(r.id)+'</code> — PR #'+r.pr_number+' — '+escapeHTML(r.state)+'</li>').join(''):'<li class="muted">No active test realms</li>';q('#build-capacity').textContent=o.build_status_available?'Up to '+o.max_concurrent_builds+' distinct PR builds can run concurrently.':'Build status is temporarily unavailable.';q('#current-builds').innerHTML=o.builds.length?o.builds.map(b=>'<li>PR #'+b.pr_number+' — '+escapeHTML(b.step||b.status)+(b.step_started_at?' <span class="muted">— current step for '+elapsedSince(b.step_started_at)+'</span>':'')+'</li>').join(''):'<li class="muted">No builds in progress</li>'}catch(e){q('#current-realms').innerHTML='<li class="error">'+escapeHTML(e.message)+'</li>';q('#current-builds').innerHTML='<li class="error">'+escapeHTML(e.message)+'</li>'}}
function elapsedSince(value){let timestamp=new Date(value).getTime(),now=Date.now();if(!Number.isFinite(timestamp)||timestamp<now-7*24*60*60*1000||timestamp>now+60*1000)return'';let seconds=Math.max(0,Math.floor((now-timestamp)/1000));return Math.floor(seconds/60)+'m '+seconds%60+'s'}
function addItem(){if(document.querySelectorAll('.item').length>=40)return alert('Maximum 40 distinct item IDs');let d=document.createElement('div');d.className='row item';d.innerHTML='<label>Item ID <input class="item-id" type="number" min="1" max="4294967295" step="1" required></label><label>Count <input class="item-count" type="number" min="1" max="200" step="1" value="1" required></label><button type="button">Remove</button>';d.querySelector('button').onclick=()=>d.remove();q('#items').append(d)}
function addQuest(){if(document.querySelectorAll('.quest').length>=100)return alert('Maximum 100 distinct quest IDs');let d=document.createElement('div');d.className='row quest';d.innerHTML='<label>Quest ID <input class="quest-id" type="number" min="1" max="4294967295" step="1" required></label><label><input class="quest-complete" type="checkbox"> Mark completed</label><button type="button">Remove</button>';d.querySelector('button').onclick=()=>d.remove();q('#quests').append(d)}
q('#add-item').onclick=addItem;q('#add-quest').onclick=addQuest;q('#realm-only').onchange=()=>q('#character').hidden=q('#realm-only').checked;
function spec(){let only=q('#realm-only').checked,items=[...document.querySelectorAll('.item')].map(x=>({id:+x.querySelector('.item-id').value,count:+x.querySelector('.item-count').value})),active=[],completed=[];for(let x of document.querySelectorAll('.quest')){let id=+x.querySelector('.quest-id').value;(x.querySelector('.quest-complete').checked?completed:active).push(id)}let chars=only?[]:[{name:q('#char-name').value.trim(),race:q('#race').value,class:q('#class').value,level:+q('#level').value,money_gold:+q('#gold').value,items,active_quests:active,completed_quests:completed}];return {summary:only?'Realm only':'Testing character '+q('#char-name').value.trim()+' with '+items.length+' item request(s) and '+(active.length+completed.length)+' quest request(s)',complete:true,realm_only:only,question:'',characters:chars}}
q('#create').onclick=async()=>{let invalid=[...document.querySelectorAll('#fixture input:not([type=checkbox])')].find(x=>!q('#realm-only').checked&&!x.checkValidity());if(invalid){invalid.reportValidity();return}if(!confirm('Create this temporary realm?'))return;q('#create').disabled=true;let operation={started:Date.now(),prNumber:+q('#prs').value,spec:spec(),stateGeneration};showLoading(operation.started);try{let session=await api('/api/sessions',{method:'POST',body:JSON.stringify({pr_number:operation.prNumber})});operation.sessionID=session.id;operation.prNumber=session.pr.number;savePending(operation);await continueProvisioning(operation)}catch(e){hideLoading();if(terminalFailure(e))clearPending();alert(e.message)}finally{q('#create').disabled=!available}};
async function continueProvisioning(operation){let x;if(!operation.realmID){setStage('build','Checking for reusable images for PR #'+operation.prNumber+'…');for(let i=0;i<2160;i++){x=await api('/api/sessions/'+operation.sessionID+'/realms',{method:'POST',body:JSON.stringify({spec:operation.spec})});if(x.realm)break;let buildDetail=x.message||x.build?.progress_detail||x.build?.step||x.build?.status||'queued';let elapsed=x.build?.step_started_at?elapsedSince(x.build.step_started_at):'';let duration=elapsed?' — '+elapsed:'';setStage('build','PR #'+operation.prNumber+': '+buildDetail+duration);setTelemetry(x.build?.progress_percent,x.build?.progress_updated_at||x.build?.step_started_at||x.build?.created_at);await loadOverview();await new Promise(r=>setTimeout(r,10000))}if(!x?.realm)throw Error('PR build or capacity wait did not finish in time');operation.realmID=x.realm.id;operation.realmListID=x.realm.realmlist_id;operation.token=x.management_token;savePending(operation)}setStage('slot','PR images are ready. Allocated realm '+operation.realmListID+'.');setTelemetry(0);q('#realm-id').value=operation.realmID;q('#realm-token').value=operation.token;let realm=await watchRealm(operation.realmID,operation.token);q('#result').hidden=false;q('#result').innerHTML=renderRealm(realm,operation.token);clearPending();await loadOverview()}
async function watchRealm(id,token){for(let i=0;i<600;i++){let d=await api('/api/realms/'+encodeURIComponent(id),{headers:{Authorization:'Bearer '+token}}),detail=d.progress_detail||d.progress||d.state,phase=d.progress_phase||'prepare',stage=phase==='ready'?'ready':phase==='workloads'||phase==='verify'?'server':phase==='prepare'||phase==='operator'?'slot':'db';setTelemetry(d.progress_percent===-1?NaN:d.progress_percent,d.progress_updated_at);if(d.state==='running'){setStage('ready','Realm verified and ready to play.');setTelemetry(100,d.progress_updated_at);hideLoading();return d}if(d.state==='failed'){clearPending();hideLoading();throw Error(d.failure||'Provisioning failed')}setStage(stage,detail);await new Promise(r=>setTimeout(r,1000))}hideLoading();throw Error('Provisioning is still running; reload this page to continue watching it.')}
function renderRealm(r,token){return '<h2>Realm ready</h2><dl class="details"><dt>Realm name</dt><dd>'+escapeHTML(r.realm_name)+'</dd><dt>Realm-list ID</dt><dd>'+r.realmlist_id+'</dd><dt>Address</dt><dd>'+escapeHTML(r.address)+':'+r.port+'</dd><dt>PR</dt><dd>#'+r.pr_number+'</dd><dt>Account</dt><dd>admin</dd><dt>Password</dt><dd>admin</dd><dt>Status</dt><dd>'+escapeHTML(r.progress)+'</dd></dl><p class="muted">Suspended after 30 minutes without a player connection; removed 48 hours after going offline.</p><p class="danger">Save these now. Do not share them.<br>Realm ID: '+escapeHTML(r.id)+'<br>Management token: '+escapeHTML(token)+'</p>'}
async function manage(action){let id=q('#realm-id').value.trim(),token=q('#realm-token').value.trim();if(!/^[a-f0-9]{24}$/.test(id)||!/^[a-f0-9]{64}$/.test(token))return alert('Realm ID or token format is invalid');let path='/api/realms/'+encodeURIComponent(id),opts={headers:{Authorization:'Bearer '+token,'Content-Type':'application/json'}};if(action==='reactivate'){path+='/reactivate';opts.method='POST';opts.body='{}'}else if(action==='delete'){if(!confirm('Permanently delete this realm and its data?'))return;opts.method='DELETE'}try{let r=await fetch(path,opts),d=await r.json().catch(()=>({state:'deleted'}));if(!r.ok)throw Error(d.error||r.statusText);q('#managed').textContent=JSON.stringify(d,null,2);await loadOverview()}catch(e){q('#managed').textContent=e.message}}
q('#inspect').onclick=()=>manage('inspect');q('#reactivate').onclick=()=>manage('reactivate');q('#delete').onclick=()=>manage('delete');function escapeHTML(v){let d=document.createElement('div');d.textContent=v??'';return d.innerHTML}async function resumePending(){let operation=readPending();if(!operation?.sessionID||!operation?.spec||!operation?.started||operation.stateGeneration!==stateGeneration){clearPending();return}showLoading(operation.started);q('#create').disabled=true;setStage(operation.realmID?'slot':'build',operation.realmID?'Reconnecting to realm '+operation.realmListID+'…':'Reconnecting to the PR #'+operation.prNumber+' build…');try{await continueProvisioning(operation)}catch(e){hideLoading();if(terminalFailure(e))clearPending();alert('Could not resume provisioning: '+e.message)}finally{q('#create').disabled=!available}}setInteractive(false);load().then(resumePending);setInterval(()=>{refreshAvailability();loadOverview()},10000);
</script></body></html>`))

func (s *Server) index(w http.ResponseWriter, _ *http.Request) {
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	_ = indexTemplate.Execute(w, nil)
}
